class Solution:
    def orderlyQueue(self, s: str, k: int) -> str:
        if k == 1:
            best = s
            for i in range(1, len(s)):
                best = min(best, s[i:] + s[:i])
            return best
        chars = list(s)
        for i in range(len(chars)):
            best = i
            for j in range(i + 1, len(chars)):
                if chars[j] < chars[best]:
                    best = j
            chars[i], chars[best] = chars[best], chars[i]
        return ''.join(chars)

