class Solution:
    def orderlyQueue(self, s, k):
        if k > 1:
            return ''.join(sorted(s))
        ss = s + s
        n = len(s)
        i, j, offset = 0, 1, 0
        while i < n and j < n and offset < n:
            a, b = ss[i + offset], ss[j + offset]
            if a == b:
                offset += 1
            elif a > b:
                i = i + offset + 1
                if i <= j:
                    i = j + 1
                offset = 0
            else:
                j = j + offset + 1
                if j <= i:
                    j = i + 1
                offset = 0
        start = min(i, j)
        return ss[start:start + n]

